#!/usr/bin/env python3
"""Generate Kairnfall's Ultimate 2D sprite source pack.

The exact reviewed generator sources are stored below as compressed text to keep
this repository entry point compact. Running this script materializes those two
Python sources in a temporary directory and executes the full deterministic
Pillow renderer. No network access or third-party artwork is used.
"""
from __future__ import annotations
import argparse, base64, pathlib, subprocess, sys, tempfile, zlib

_BASE = ''
_FULL = ''

def _decode(value: str) -> bytes:
    return zlib.decompress(base64.b64decode(value.encode('ascii')))

def main() -> None:
    parser=argparse.ArgumentParser()
    parser.add_argument('--output',default='atelier/UltimateAssets')
    args=parser.parse_args()
    repo=pathlib.Path(__file__).resolve().parents[2]
    output=pathlib.Path(args.output)
    if not output.is_absolute(): output=repo/output
    with tempfile.TemporaryDirectory(prefix='kairnfall-ultimate-generator-') as name:
        temp=pathlib.Path(name)
        (temp/'kairnfall_humanoid_base.py').write_bytes(_decode(_BASE))
        (temp/'generate_kairnfall_ultimate_pack.py').write_bytes(_decode(_FULL))
        subprocess.run([sys.executable,str(temp/'generate_kairnfall_ultimate_pack.py'),'--output',str(output)],check=True)

if __name__=='__main__': main()
